const server = $fromAI('server', 'Server hostname to check, e.g. fs01.internal', 'string');
const metric = $fromAI('metric', 'Metric type: cpu, memory, disk, services, logs, or all', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/check-service-status', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ server, metric })
});
return await resp.text();

const username = $fromAI('username', 'The username to look up, e.g. jsmith', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/lookup-asset', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ username })
});
return await resp.text();

const query = $fromAI('query', 'Search query text for the knowledge base', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/query-kb', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ query, collection: 'helpdesk_kb' })
});
return await resp.text();

const ticket_id = $fromAI('ticket_id', 'The ticket ID to update', 'string');
const category = $fromAI('category', 'Issue category e.g. Infrastructure - File Services', 'string');
const priority = $fromAI('priority', 'Priority level: critical, high, medium, or low', 'string');
const assigned_team = $fromAI('assigned_team', 'Team to assign the ticket to', 'string');
const summary = $fromAI('summary', 'Brief triage summary with evidence', 'string');
const action1 = $fromAI('action1', 'First recommended action', 'string');
const action2 = $fromAI('action2', 'Second recommended action', 'string');

const resp = await fetch('http://mcp-server:3001/api/tools/update-ticket', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ ticket_id, category, priority, assigned_team, summary, action1, action2 })
});
return await resp.text();
